edits.before:
onClick (event) {
  if (event.target.closest(`[${ this.config.closeTrigger }]`)) {
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}

edits.after:
onClick (event) {
  const closeElement = event.target.closest(`[${ this.config.closeTrigger }]`)
  if (closeElement) {
    if (closeElement === this.modal && event.target !== this.modal) {
      // click is inside the modal, not on the overlay background
      return
    }
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}

