onClick (event) {
  const closeElement = event.target.closest(`[${ this.config.closeTrigger }]`)
  if (closeElement) {
    // If the close trigger is the overlay (direct child of modal) and the click target is not the overlay itself, ignore
    if (closeElement.parentElement === this.modal && event.target !== closeElement) {
      return
    }
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}
